// visualizer.js — Bent Line's picture for the CRT: the glowing line.
// GENERATED by ui/make_visualizer.py from ui/visualizer.template.js. Edit the template.
//
// The page's whole argument fits on one screen. A flat horizontal line is the harmonic
// series; every bend away from it is a material. So:
//
//  - Partial number runs left to right, 1 to 64. The bold line across the middle is
//    zero cents: every partial exactly on its harmonic. It is always there.
//  - The glowing line is Wavetable B now: each partial drawn at its bend in cents (times
//    the Bend knob), on a scale that keeps ten cents and two octaves both visible.
//    Its brightness along its length is Wavetable A: bright where the partial is loud.
//  - Behind it, faint, every frame of the material's measured trajectory at this bend,
//    the nearest frames brighter. A piano note walks from its attack frame toward the
//    flat line; you watch the line settle into the ghost it is heading for.
//  - The line is redrawn here from the engine's own tables (the same numbers
//    Constants.h holds), at the frame position and age the plugin reports for its newest
//    voice. Levels follow the engine: the wall, times velocity, envelope, and each
//    partial's own decay. Partials above about 20 kHz go dark (the screen assumes 44.1 kHz).
//  - Drag on the glass: up and down is Bend, so you bend the line by hand; left and
//    right is A position. A drag is the knob moving, with automation.
//
// Contract with the editor (VST Template machinery/ui/editor.html, § the CRT's picture):
//   BentLineGlow.mount(el, hooks)       draws into el; hooks { get, set, begin, end } by id
//   BentLineGlow.frame(probes, params)  probes in kProbes order:
//                                       pos, bend16, voices, npos, age, env, vel, f0
// Nothing else is read; nothing is fetched.
const BentLineGlow = (() => {
/*@DATA@*/
  const NP = 64, NF = 16, NO = 48;
  const PHOS = [124, 255, 178], AMBER = [255, 179, 71], INK = [200, 255, 225];
  const NOTE = ["C", "C♯", "D", "D♯", "E", "F", "F♯", "G", "G♯", "A", "A♯", "B"];
  const SPAN = Math.log1p(2400 / 20);
  let el = null, cv = null, g = null, W = 0, H = 0, dpr = 1, hooks = null, drag = null;
  let now = { mat: 3, fil: 0, bend: 1, clock: 0, bpos: 0, wall: 0, apos: 0.55, decay: 3,
              pos: 0, age: 0, env: 0, vel: 0, f0: 0, voices: 0 };

  const rgba = (c, a) => `rgba(${c[0]},${c[1]},${c[2]},${Math.max(0, Math.min(1, a))})`;
  const cents = (m, fl, fr, s) => BL_DATA.cents[((m * 2 + fl) * NF + fr) * NP + s];
  const own = (m, fl, fr, s) => BL_DATA.own[((m * 2 + fl) * NF + fr) * NP + s];
  const mask = (m, fl, s) => BL_DATA.mask[(m * 2 + fl) * NP + s];
  const organ = (fr, s) => BL_DATA.organ[fr * NP + s];
  const lerp = (get, pos, n, s) => {
    const lo = Math.floor(pos), a = pos - lo;
    return lo >= n - 1 ? get(n - 1, s) : get(lo, s) * (1 - a) + get(lo + 1, s) * a;
  };
  function noteName(f) {
    if (!(f > 0)) return "";
    const m = Math.round(69 + 12 * Math.log2(f / 440));
    return NOTE[((m % 12) + 12) % 12] + (Math.floor(m / 12) - 1);
  }

  // the plot: partial number across, cents up and down on a signed log scale
  let L = 0, R = 0, T = 0, B = 0, CY = 0;
  const xOf = s => L + (s / (NP - 1)) * (R - L);
  const yOf = c => CY - Math.sign(c) * (Math.log1p(Math.abs(c) / 20) / SPAN) * (CY - T);
  const cOfY = y => { const u = (CY - y) / (CY - T) * SPAN; return Math.sign(u) * 20 * Math.expm1(Math.abs(u)); };

  function mount(target, h) {
    el = target; hooks = h || null;
    cv = document.createElement("canvas");
    cv.style.cssText = "width:100%;height:100%;display:block;cursor:ns-resize;touch-action:none";
    el.append(cv);
    g = cv.getContext("2d");
    const fit = () => {
      dpr = Math.min(2, window.devicePixelRatio || 1);
      W = el.clientWidth; H = el.clientHeight;
      if (!W || !H) return;
      cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
      draw();
    };
    if (window.ResizeObserver) new ResizeObserver(fit).observe(el);
    fit();

    // drag: up and down is Bend (0..2), left and right is A position (0..1)
    const at = e => { const r = cv.getBoundingClientRect(); return [(e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height]; };
    cv.addEventListener("pointerdown", e => {
      if (!hooks) return;
      cv.setPointerCapture(e.pointerId);
      const [x, y] = at(e);
      drag = { x, y, bend: hooks.get("bend") ?? now.bend, apos: hooks.get("apos") ?? now.apos };
      hooks.begin("bend"); hooks.begin("apos");
    });
    cv.addEventListener("pointermove", e => {
      if (!drag) return;
      const [x, y] = at(e);
      hooks.set("bend", Math.max(0, Math.min(2, drag.bend - (y - drag.y) * 2.5)));
      hooks.set("apos", Math.max(0, Math.min(1, drag.apos + (x - drag.x) * 1.2)));
    });
    const up = () => { if (!drag) return; drag = null; hooks.end("bend"); hooks.end("apos"); };
    cv.addEventListener("pointerup", up);
    cv.addEventListener("pointercancel", up);
  }

  function frame(probes, params) {
    params = params || {}; probes = probes || [];
    const n = k => Number.isFinite(probes[k]) ? probes[k] : 0;
    now = {
      mat: Math.round(params.material ?? 3), fil: Math.round(params.filing ?? 0),
      bend: params.bend ?? 1, clock: Math.round(params.clock ?? 0), bpos: params.bpos ?? 0,
      wall: Math.round(params.wall ?? 0), apos: params.apos ?? 0.55, decay: params.decay ?? 3,
      voices: n(2), pos: n(3), age: n(4), env: n(5), vel: n(6), f0: n(7),
    };
    draw();
  }

  // the line now: bend and level for every slot, as the engine computes them
  function line() {
    const { mat, fil, bend, wall, apos, decay, env, vel, age, f0 } = now;
    const pos = now.voices > 0 ? now.pos : (now.clock === 1 ? now.bpos * (NF - 1) : now.pos);
    const c = new Float32Array(NP), A = new Float32Array(NP), live = new Float32Array(NP);
    for (let s = 0; s < NP; ++s) {
      c[s] = bend * lerp((fr, q) => cents(mat, fil, fr, q), pos, NF, s);
      A[s] = wall === 0 ? lerp(organ, apos * (NO - 1), NO, s) * mask(mat, fil, s)
                        : lerp((fr, q) => own(mat, fil, fr, q), pos, NF, s);
      const f = (s + 1) * f0 * Math.pow(2, c[s] / 1200);
      const tau = decay / (1 + 0.07 * s);
      live[s] = f0 > 0 && f >= 0.45 * 44100 ? 0 : A[s] * vel * env * Math.exp(-age / tau);
    }
    return { c, A, live, pos };
  }

  function draw() {
    if (!g || !W || !H) return;
    g.setTransform(dpr, 0, 0, dpr, 0, 0);
    g.globalCompositeOperation = "source-over";
    g.fillStyle = "#020604"; g.fillRect(0, 0, W, H);
    const fs = Math.max(10, Math.min(14, H * 0.03));
    L = fs * 4.2; R = W - fs * 1.6; T = fs * 3.4; B = H - fs * 3.2; CY = (T + B) / 2;
    const { mat, fil, bend } = now;
    const { c, A, live, pos } = line();

    // the scale: ten cents, a semitone, an octave, two, each side of the flat line
    g.font = `${fs * 0.8}px "JetBrains Mono", ui-monospace, monospace`;
    g.lineWidth = 1; g.setLineDash([2, 5]);
    for (const [v, lab] of [[10, "10¢"], [100, "100¢"], [1200, "8va"], [2400, "2·8va"]]) {
      for (const sg of [1, -1]) {
        const y = yOf(sg * v);
        g.strokeStyle = rgba(PHOS, 0.10);
        g.beginPath(); g.moveTo(L, y); g.lineTo(R, y); g.stroke();
        g.fillStyle = rgba(PHOS, 0.32);
        g.fillText((sg > 0 ? "+" : "−") + lab, fs * 0.4, y + fs * 0.3);
      }
    }
    g.setLineDash([]);
    for (const s of [0, 7, 15, 31, 47, 63]) {
      g.fillStyle = rgba(PHOS, 0.32);
      g.fillText(String(s + 1), xOf(s) - fs * 0.3, B + fs * 1.3);
    }

    // the flat line: the harmonic series, always there
    g.strokeStyle = rgba(INK, bend === 0 ? 0.9 : 0.55); g.lineWidth = 2;
    g.beginPath(); g.moveTo(L, CY); g.lineTo(R, CY); g.stroke();

    g.globalCompositeOperation = "lighter";

    // the ghosts: every frame of the measured trajectory, at this bend
    for (let fr = 0; fr < NF; ++fr) {
      const near = Math.exp(-Math.abs(fr - pos) * 0.9);
      g.strokeStyle = rgba(AMBER, 0.08 + 0.35 * near); g.lineWidth = 1;
      g.beginPath();
      let pen = false;
      for (let s = 0; s < NP; ++s) {
        if (!mask(mat, fil, s)) { pen = false; continue; }
        const x = xOf(s), y = yOf(bend * cents(mat, fil, fr, s));
        if (pen) g.lineTo(x, y); else g.moveTo(x, y);
        pen = true;
      }
      g.stroke();
    }

    // the line: bend as height, level as light. At rest it shows dim; a note lights it
    const lum = s => Math.min(1, 0.10 + 0.35 * Math.sqrt(A[s]) + 0.9 * Math.sqrt(live[s]));
    for (let s = 0; s < NP - 1; ++s) {
      if (!mask(mat, fil, s) || !mask(mat, fil, s + 1)) continue;
      const b = (lum(s) + lum(s + 1)) / 2;
      const x0 = xOf(s), y0 = yOf(c[s]), x1 = xOf(s + 1), y1 = yOf(c[s + 1]);
      g.strokeStyle = rgba(PHOS, 0.22 * b); g.lineWidth = 2 + 7 * b;
      g.beginPath(); g.moveTo(x0, y0); g.lineTo(x1, y1); g.stroke();
      g.strokeStyle = rgba(INK, 0.25 + 0.7 * b); g.lineWidth = 1.2 + 0.8 * b;
      g.beginPath(); g.moveTo(x0, y0); g.lineTo(x1, y1); g.stroke();
    }
    for (let s = 0; s < NP; ++s) {
      const x = xOf(s), y = yOf(c[s]);
      if (!mask(mat, fil, s)) {   // an empty slot: silent under this filing
        g.strokeStyle = rgba(PHOS, 0.12); g.lineWidth = 1;
        g.beginPath(); g.arc(x, CY, 1.5, 0, 2 * Math.PI); g.stroke();
        continue;
      }
      const b = lum(s), r = 2 + 9 * b;
      const gr = g.createRadialGradient(x, y, 0, x, y, r);
      gr.addColorStop(0, rgba(INK, 0.9 * b)); gr.addColorStop(0.35, rgba(PHOS, 0.45 * b)); gr.addColorStop(1, rgba(PHOS, 0));
      g.fillStyle = gr; g.fillRect(x - r, y - r, 2 * r, 2 * r);
      if (Math.abs(c[s]) > 0.5) {   // a hair from the flat line to the partial: how far it bent
        g.strokeStyle = rgba(PHOS, 0.07 + 0.2 * b); g.lineWidth = 1;
        g.beginPath(); g.moveTo(x, CY); g.lineTo(x, y); g.stroke();
      }
    }

    // readouts, in the dress's mono: two lines left, two right-aligned, the hint below
    g.globalCompositeOperation = "source-over";
    g.font = `${fs}px "JetBrains Mono", ui-monospace, monospace`;
    const name = (BL_DATA.names[mat] || "").toUpperCase();
    const left = (txt, col, a, y) => { g.textAlign = "left"; g.fillStyle = rgba(col, a); g.fillText(txt, L - fs * 2.6, y); };
    const right = (txt, col, a, y) => { g.textAlign = "right"; g.fillStyle = rgba(col, a); g.fillText(txt, R - fs * 0.6, y); };
    left(`${name} · ${fil ? "NEAREST" : "RANK"} · bend ${bend.toFixed(2)}×`, PHOS, 0.8, fs * 1.6);
    const lo = Math.min(NF - 2, Math.floor(pos)), a = pos - lo;
    const t = BL_DATA.times[mat * NF + lo] * (1 - a) + BL_DATA.times[mat * NF + lo + 1] * a;
    const note = now.voices > 0 && now.f0 > 0 ? `${noteName(now.f0)} · ` : "";
    left(note + (now.clock === 1 ? `manual · frame ${pos.toFixed(1)} of ${NF - 1}`
                                 : `${t.toFixed(2)} s into the ${BL_DATA.names[mat].toLowerCase()}`), AMBER, 0.7, fs * 2.8);
    const sixteen = mask(mat, fil, 15) ? `partial 16 ${c[15] >= 0 ? "+" : "−"}${Math.abs(c[15]).toFixed(1)}¢` : "partial 16 silent";
    right(bend === 0 ? "FLAT · harmonic" : sixteen, bend === 0 ? INK : PHOS, bend === 0 ? 0.95 : 0.65, fs * 1.6);
    right(now.wall ? "wall · its own levels" : `wall · organ ${now.apos.toFixed(2)}`, PHOS, 0.42, fs * 2.8);
    right("drag ↑↓ bend · ←→ A", PHOS, 0.3, H - fs * 0.9);
    left("partial →", PHOS, 0.3, H - fs * 0.9);
    g.textAlign = "left";
  }

  return { mount, frame };
})();
